use core::fmt::Write;
use std::rc::Rc;

use slint::{FilterModel, Model, ModelRc, SharedString, VecModel};

use crate::ui_sync::bitops::{BitSet256, CellBitSet256, StackFmt, MAX_TWEAKS};
use crate::ui_sync::selection::{FilterStrictSelection, FilterableEntry};

// Generated by `slint::include_modules!()` from `ui/optimizer_bridge.slint`.
use crate::{TelemetryMetricData, TweakItemData, TweakStatus};

/// Compact, `Copy` backend status mapped 1:1 to Slint's `TweakStatus`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
#[repr(u8)]
pub enum BackendTweakStatus {
    #[default]
    Pending = 0,
    Queued = 1,
    Running = 2,
    Applied = 3,
    Failed = 4,
    Skipped = 5,
}

impl From<BackendTweakStatus> for TweakStatus {
    #[inline]
    fn from(s: BackendTweakStatus) -> Self {
        match s {
            BackendTweakStatus::Pending => TweakStatus::Pending,
            BackendTweakStatus::Queued => TweakStatus::Queued,
            BackendTweakStatus::Running => TweakStatus::Running,
            BackendTweakStatus::Applied => TweakStatus::Applied,
            BackendTweakStatus::Failed => TweakStatus::Failed,
            BackendTweakStatus::Skipped => TweakStatus::Skipped,
        }
    }
}

/// Zero-allocation typed backend value for 100 ms snapshots.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BackendTweakValue {
    None,
    Bool(bool),
    Int(i64),
    /// Fixed-point tenths (e.g. `142` -> `"14.2 ms"`).
    MillisTenths(i32),
    /// Fixed-point tenths (e.g. `995` -> `"99.5%"`).
    PercentTenths(u16),
    Megabytes(u32),
    Static(&'static str),
}

impl Default for BackendTweakValue {
    fn default() -> Self {
        Self::None
    }
}

/// 100 ms backend snapshot row (strictly `Copy`, passed as `&[TweakSnapshot]`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct TweakSnapshot {
    pub status: BackendTweakStatus,
    pub value: BackendTweakValue,
}

/// Immutable descriptor used once at startup to populate the `VecModel`.
pub struct TweakStaticDescriptor {
    pub id: &'static str,
    pub title: &'static str,
    pub category: &'static str,
    pub protected: bool,
    pub selectable: bool,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct TweakShadow {
    status: BackendTweakStatus,
    value: BackendTweakValue,
    selected: bool,
    protected: bool,
}

/// Pre-interned Slint `SharedString` LUT (cloning is an atomic/non-atomic refcount bump).
struct PreInternedStrings {
    statuses: [SharedString; 6],
    enabled: SharedString,
    disabled: SharedString,
    dash: SharedString,
}

impl PreInternedStrings {
    fn new() -> Self {
        Self {
            statuses: [
                SharedString::from("Pending"),
                SharedString::from("Queued"),
                SharedString::from("Running"),
                SharedString::from("Applied"),
                SharedString::from("Failed"),
                SharedString::from("Skipped"),
            ],
            enabled: SharedString::from("Enabled"),
            disabled: SharedString::from("Disabled"),
            dash: SharedString::from("—"),
        }
    }

    #[inline]
    fn status(&self, s: BackendTweakStatus) -> SharedString {
        self.statuses[s as usize].clone()
    }
}

/// Differential synchronizer for up to 256 tweaks backed by a persistent `VecModel`
/// and a `FilterModel` reading a `CellBitSet256`.
pub struct TweakDiffSync {
    count: usize,
    backing: Rc<VecModel<TweakItemData>>,
    filtered: Rc<FilterModel<Rc<VecModel<TweakItemData>>, Box<dyn Fn(&TweakItemData) -> bool>>>,
    visible_cell: Rc<CellBitSet256>,
    shadow: [TweakShadow; MAX_TWEAKS],
    static_meta: Vec<TweakStaticDescriptor>,
    lut: PreInternedStrings,
    pub selection: FilterStrictSelection,
}

impl TweakDiffSync {
    /// Allocates the `VecModel` and `FilterModel` once at startup.
    pub fn new(descriptors: Vec<TweakStaticDescriptor>) -> Self {
        let count = descriptors.len().min(MAX_TWEAKS);
        let lut = PreInternedStrings::new();

        let mut protected_mask = BitSet256::EMPTY;
        let mut selectable_mask = BitSet256::EMPTY;
        let mut rows = Vec::with_capacity(count);
        let mut shadow = [TweakShadow::default(); MAX_TWEAKS];

        for (idx, desc) in descriptors.iter().take(count).enumerate() {
            if desc.protected {
                protected_mask.set(idx);
            }
            if desc.selectable {
                selectable_mask.set(idx);
            }
            shadow[idx] = TweakShadow {
                status: BackendTweakStatus::Pending,
                value: BackendTweakValue::None,
                selected: false,
                protected: desc.protected,
            };
            rows.push(TweakItemData {
                index: idx as i32,
                id: SharedString::from(desc.id),
                title: SharedString::from(desc.title),
                category: SharedString::from(desc.category),
                status: TweakStatus::Pending,
                status_label: lut.status(BackendTweakStatus::Pending),
                value_text: lut.dash.clone(),
                selected: false,
                protected: desc.protected,
            });
        }

        let selection = FilterStrictSelection::new(count, protected_mask, selectable_mask);
        let visible_cell = Rc::new(CellBitSet256::new(selection.visible_mask()));
        let backing = Rc::new(VecModel::from(rows));

        let pred_mask = Rc::clone(&visible_cell);
        let predicate: Box<dyn Fn(&TweakItemData) -> bool> =
            Box::new(move |row: &TweakItemData| pred_mask.contains(row.index as usize));

        let filtered = Rc::new(FilterModel::new(Rc::clone(&backing), predicate));

        Self {
            count,
            backing,
            filtered,
            visible_cell,
            shadow,
            static_meta: descriptors,
            lut,
            selection,
        }
    }

    /// Returns the `ModelRc` bound once to Slint's `ListView`.
    #[inline]
    pub fn model_rc(&self) -> ModelRc<TweakItemData> {
        ModelRc::from(Rc::clone(&self.filtered))
    }

    /// Hot-path 100 ms tick reconciler.
    /// Zero heap allocations when rows are unchanged or only flip between static values/statuses.
    /// Returns the number of mutated rows.
    pub fn sync_tick(&mut self, snapshots: &[TweakSnapshot]) -> usize {
        let len = snapshots.len().min(self.count);
        let mut fmt_buf = StackFmt::<64>::new();
        let mut mutated = 0usize;

        for (idx, snap) in snapshots.iter().take(len).enumerate() {
            let selected = self.selection.is_selected(idx);
            let protected = self.selection.is_protected(idx);
            let prev = self.shadow[idx];

            let status_changed = snap.status != prev.status;
            let value_changed = snap.value != prev.value;
            let sel_changed = selected != prev.selected;
            let prot_changed = protected != prev.protected;

            if !(status_changed || value_changed || sel_changed || prot_changed) {
                continue;
            }

            let Some(mut row) = self.backing.row_data(idx) else {
                continue;
            };

            if status_changed {
                row.status = snap.status.into();
                row.status_label = self.lut.status(snap.status);
            }
            if value_changed {
                self.write_value(&mut row.value_text, snap.value, &mut fmt_buf);
            }
            if sel_changed {
                row.selected = selected;
            }
            if prot_changed {
                row.protected = protected;
            }

            self.backing.set_row_data(idx, row);
            self.shadow[idx] = TweakShadow {
                status: snap.status,
                value: snap.value,
                selected,
                protected,
            };
            mutated += 1;
        }

        mutated
    }

    /// Applies selection delta mask immediately on user clicks without scanning all 230 rows.
    pub fn flush_selection_delta(&mut self, delta: BitSet256) {
        for idx in delta.iter_ones() {
            if idx >= self.count {
                break;
            }
            let selected = self.selection.is_selected(idx);
            if self.shadow[idx].selected == selected {
                continue;
            }
            if let Some(mut row) = self.backing.row_data(idx) {
                row.selected = selected;
                self.backing.set_row_data(idx, row);
                self.shadow[idx].selected = selected;
            }
        }
    }

    /// Updates the active search/category filter and refreshes `FilterModel` only when changed.
    pub fn update_filter(&mut self, query: &str, category: Option<&str>) {
        let entries = self.static_meta.iter().take(self.count).map(|d| FilterableEntry {
            id: d.id,
            title: d.title,
            category: d.category,
        });
        if self.selection.apply_filter(query, category, entries) {
            self.visible_cell.replace(self.selection.visible_mask());
            self.filtered.reset();
        }
    }

    #[inline]
    fn write_value(
        &self,
        target: &mut SharedString,
        value: BackendTweakValue,
        buf: &mut StackFmt<64>,
    ) {
        match value {
            BackendTweakValue::None => *target = self.lut.dash.clone(),
            BackendTweakValue::Bool(true) => *target = self.lut.enabled.clone(),
            BackendTweakValue::Bool(false) => *target = self.lut.disabled.clone(),
            BackendTweakValue::Static(s) => {
                if target.as_str() != s {
                    *target = SharedString::from(s);
                }
            }
            BackendTweakValue::Int(v) => {
                buf.clear();
                let _ = write!(buf, "{v}");
                if target.as_str() != buf.as_str() {
                    *target = SharedString::from(buf.as_str());
                }
            }
            BackendTweakValue::MillisTenths(t) => {
                buf.clear();
                let sign = if t < 0 { "-" } else { "" };
                let abs = t.unsigned_abs();
                let _ = write!(buf, "{sign}{}.{} ms", abs / 10, abs % 10);
                if target.as_str() != buf.as_str() {
                    *target = SharedString::from(buf.as_str());
                }
            }
            BackendTweakValue::PercentTenths(p) => {
                buf.clear();
                let _ = write!(buf, "{}.{}%", p / 10, p % 10);
                if target.as_str() != buf.as_str() {
                    *target = SharedString::from(buf.as_str());
                }
            }
            BackendTweakValue::Megabytes(mb) => {
                buf.clear();
                if mb >= 1024 {
                    let tenths_gb = (mb as u64 * 10) / 1024;
                    let _ = write!(buf, "{}.{} GB", tenths_gb / 10, tenths_gb % 10);
                } else {
                    let _ = write!(buf, "{mb} MB");
                }
                if target.as_str() != buf.as_str() {
                    *target = SharedString::from(buf.as_str());
                }
            }
        }
    }
}

// -----------------------------------------------------------------------------
// Telemetry Differential Synchronizer (Fixed-Channel Deadband Quantization)
// -----------------------------------------------------------------------------

pub const MAX_TELEMETRY_CHANNELS: usize = 32;

#[derive(Clone, Copy, Debug)]
pub struct TelemetryChannelSpec {
    pub key: &'static str,
    pub label: &'static str,
    pub unit: &'static str,
    /// Fixed-point scale factor (e.g. `10` = tenths).
    pub scale: i32,
    /// Minimum quantized delta required to emit a `set_row_data` repaint.
    pub deadband: i32,
    pub min_quantized: i32,
    pub max_quantized: i32,
    pub warning_threshold: i32,
}

#[derive(Clone, Copy, Debug, Default)]
struct TelemetryShadow {
    quantized: i32,
    warning: bool,
    initialized: bool,
}

pub struct TelemetryDiffSync {
    count: usize,
    backing: Rc<VecModel<TelemetryMetricData>>,
    specs: [Option<TelemetryChannelSpec>; MAX_TELEMETRY_CHANNELS],
    shadow: [TelemetryShadow; MAX_TELEMETRY_CHANNELS],
}

impl TelemetryDiffSync {
    pub fn new(specs_slice: &[TelemetryChannelSpec]) -> Self {
        let count = specs_slice.len().min(MAX_TELEMETRY_CHANNELS);
        let mut specs = [None; MAX_TELEMETRY_CHANNELS];
        let mut rows = Vec::with_capacity(count);

        for (i, spec) in specs_slice.iter().take(count).enumerate() {
            specs[i] = Some(*spec);
            rows.push(TelemetryMetricData {
                key: SharedString::from(spec.key),
                label: SharedString::from(spec.label),
                formatted_value: SharedString::from("—"),
                unit: SharedString::from(spec.unit),
                normalized_ratio: 0.0,
                warning: false,
            });
        }

        Self {
            count,
            backing: Rc::new(VecModel::from(rows)),
            specs,
            shadow: [TelemetryShadow::default(); MAX_TELEMETRY_CHANNELS],
        }
    }

    #[inline]
    pub fn model_rc(&self) -> ModelRc<TelemetryMetricData> {
        ModelRc::from(Rc::clone(&self.backing))
    }

    /// Reconciles quantized telemetry readings (e.g., `458` for `45.8°C` when `scale = 10`).
    /// Sub-deadband sensor noise triggers zero `set_row_data` calls and zero allocations.
    pub fn sync_readings(&mut self, quantized_values: &[i32]) -> usize {
        let len = quantized_values.len().min(self.count);
        let mut fmt_buf = StackFmt::<32>::new();
        let mut mutated = 0usize;

        for (idx, &raw) in quantized_values.iter().take(len).enumerate() {
            let Some(spec) = self.specs[idx] else {
                continue;
            };
            let prev = self.shadow[idx];
            let warning = raw >= spec.warning_threshold;

            if prev.initialized
                && prev.warning == warning
                && raw.saturating_sub(prev.quantized).abs() < spec.deadband
            {
                continue;
            }

            let Some(mut row) = self.backing.row_data(idx) else {
                continue;
            };

            fmt_buf.clear();
            if spec.scale <= 1 {
                let _ = write!(fmt_buf, "{raw}");
            } else {
                let sign = if raw < 0 { "-" } else { "" };
                let abs = raw.unsigned_abs();
                let sc = spec.scale as u32;
                let _ = write!(fmt_buf, "{sign}{}.{}", abs / sc, abs % sc);
            }

            if row.formatted_value.as_str() != fmt_buf.as_str() {
                row.formatted_value = SharedString::from(fmt_buf.as_str());
            }

            let span = (spec.max_quantized - spec.min_quantized).max(1) as f32;
            row.normalized_ratio = ((raw - spec.min_quantized) as f32 / span).clamp(0.0, 1.0);
            row.warning = warning;

            self.backing.set_row_data(idx, row);
            self.shadow[idx] = TelemetryShadow {
                quantized: raw,
                warning,
                initialized: true,
            };
            mutated += 1;
        }

        mutated
    }
}